#!/bin/bash
set -e

# Fix: the idle timer was purely client-side, so it could never catch
# 'closed the tab/browser and came back hours later' -- no JS was
# running during that gap to enforce anything, and the session cookie
# was still valid regardless. Real enforcement now happens server-side
# in middleware on every navigation, checking profiles.last_active_at.
#
# Throttled via a short-lived cookie so it only actually hits the
# database about once every 2 minutes per person, not on every single
# request. last_active_at is now also set immediately at login itself
# (not just the client heartbeat, which can be up to 60s behind) --
# otherwise a stale value could immediately boot someone right after
# they just signed in.
# Run this from your veda-hmis repo root in Codespaces.

echo "" | base64 -d > "middleware.js"
echo "Wrote middleware.js"

mkdir -p "app/login"
echo "" | base64 -d > "app/login/page.js"
echo "Wrote app/login/page.js"

mkdir -p "app/components"
echo "" | base64 -d > "app/components/AppShell.js"
echo "Wrote app/components/AppShell.js"

git add "middleware.js" "app/login/page.js" "app/components/AppShell.js"
git commit -m "Fix idle auto-logout: enforce server-side in middleware, not just client-side timer"
git push

echo "Done."
